<?php
require_once __DIR__.'/lesson_policy.php';
require_once __DIR__.'/payroll_lesson_link.php';
function paCategories(){return ['演習','小学生','中学生','高校生','その他'];}
function paCategory($row){$explicit=trim((string)($row['給与区分']??''));if(in_array($explicit,paCategories(),true))return $explicit;$class=trim((string)($row['クラス']??''));if(trim((string)($row['種別']??''))==='演習')return '演習';foreach(['小学生'=>'/^小|小学/u','中学生'=>'/^中|中学/u','高校生'=>'/^高|高校/u'] as $name=>$pattern)if(preg_match($pattern,$class))return $name;return 'その他';}
function paAmount($rate){if(!array_key_exists('amount',$rate))return null;$v=$rate['amount'];if($v===null||$v===''||$v===false)return 0;if($v===true)return 1;if(!is_numeric($v))return null;$n=0+$v;return is_finite((float)$n)&&$n>=0?$n:null;}
function paDefaultRate($teacher,$category,$rates){foreach([$category,''] as $cat)foreach($rates as $r)if(trim((string)($r['teacher']??''))===$teacher&&trim((string)($r['class']??''))===''&&trim((string)($r['category']??''))===$cat){$value=paAmount($r);if($value!==null)return $value;break;}return null;}
function paRate($teacher,$class,$category,$rates){$matches=array_values(array_filter($rates,function($r)use($teacher,$class){return trim((string)($r['teacher']??''))===$teacher&&trim((string)($r['class']??''))===$class;}));if($matches){$chosen=$matches[0];foreach($matches as $r)if(trim((string)($r['category']??''))===''){$chosen=$r;break;}if(paAmount($chosen)!==null)return paAmount($chosen);}return paDefaultRate($teacher,$category,$rates);}
function paRowDate($value){if(!preg_match('~(\d{4})/(\d{1,2})/(\d{1,2})~',str_replace('-','/',(string)$value),$m))return '';return sprintf('%04d-%02d-%02d',(int)$m[1],(int)$m[2],(int)$m[3]);}
function paDate($value){if(!is_string($value)||!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D',$value,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))staffFail('対象期間の日付を確認してください',400);return $value;}
function paScope($input){$teacher=$input['teacher']??null;if(!is_string($teacher)||trim($teacher)===''||strlen($teacher)>600)staffFail('講師を選択してください',400);$from=paDate($input['from']??null);$to=paDate($input['to']??null);if($from>$to)staffFail('開始日と終了日を確認してください',400);return ['teacher'=>trim($teacher),'from'=>$from,'to'=>$to];}
function paScopeId($scope){return hash('sha256',json_encode(array_values($scope),JSON_UNESCAPED_UNICODE));}
function paRevision($entry){return hash('sha256',json_encode($entry,JSON_UNESCAPED_UNICODE));}
function paGroupId($category,$rate){return hash('sha256',json_encode([$category,$rate],JSON_UNESCAPED_UNICODE));}
function paModel($scope,$store){
 $rows=policyRows();$rates=readJsonStrict(__DIR__.'/data/payroll_rates.json');$groups=[];$otherLessons=[];$known=false;$teacher=$scope['teacher'];$seen=[];
 foreach($rows as $row){if(trim((string)($row['担当講師']??''))!==$teacher)continue;$known=true;if(trim((string)($row['日区分']??''))!=='')continue;$category=paCategory($row);$class=trim((string)($row['クラス']??''));$rate=paRate($teacher,$class,$category,$rates);$id=paGroupId($category,$rate);if(!isset($seen[$category][$id]))$seen[$category][$id]=['id'=>$id,'category'=>$category,'rate'=>$rate,'plannedCount'=>0,'classes'=>[]];$seen[$category][$id]['classes'][]=$class;$date=paRowDate($row['日付']??'');if($date<$scope['from']||$date>$scope['to'])continue;if(!isset($groups[$id]))$groups[$id]=['id'=>$id,'category'=>$category,'rate'=>$rate,'plannedCount'=>0,'classes'=>[]];$groups[$id]['plannedCount']++;$groups[$id]['classes'][]=$class;if($category==='その他')$otherLessons[]=payrollOtherLesson($row);
 }
 if(!$known)staffFail('講師が時間割に見つかりません',404);
 foreach(array_slice(paCategories(),0,4) as $category){$present=false;foreach($groups as $g)if($g['category']===$category)$present=true;if($present)continue;if(!empty($seen[$category])){foreach($seen[$category] as $id=>$g)$groups[$id]=$g;}else{$rate=paDefaultRate($teacher,$category,$rates);$id=paGroupId($category,$rate);$groups[$id]=['id'=>$id,'category'=>$category,'rate'=>$rate,'plannedCount'=>0,'classes'=>[]];}}
 // A rate edit keeps counts when the underlying category/classes remain the same.
 $stable=[];foreach($groups as $g){$g['classes']=array_values(array_unique($g['classes']));sort($g['classes'],SORT_NATURAL);$g['id']=hash('sha256',json_encode([$g['category'],$g['classes']],JSON_UNESCAPED_UNICODE));$stable[$g['id']]=$g;}$groups=$stable;ksort($groups);$basis=hash('sha256',json_encode($groups,JSON_UNESCAPED_UNICODE));$entry=$store[paScopeId($scope)]??null;$overrides=$entry['overrides']??[];if(!is_array($overrides))dataError('給与調整の保存形式を確認してください');foreach($overrides as $count)if(!is_int($count)||$count<0)dataError('給与調整の保存値を確認してください');$planned=0;$final=0;$plannedCount=0;$finalCount=0;$missing=false;$plannedMissing=false;
 foreach($groups as $id=>&$g){$g['adjusted']=array_key_exists($id,$overrides);$g['finalCount']=$g['adjusted']?$overrides[$id]:$g['plannedCount'];$g['adjustable']=$g['category']!=='その他';$g['plannedPay']=$g['rate']===null&&$g['plannedCount']>0?null:$g['rate']*$g['plannedCount'];$g['finalPay']=$g['rate']===null&&$g['finalCount']>0?null:$g['rate']*$g['finalCount'];$plannedMissing=$plannedMissing||$g['plannedPay']===null;$missing=$missing||$g['finalPay']===null;$planned+=$g['plannedPay']??0;$final+=$g['finalPay']??0;$plannedCount+=$g['plannedCount'];$finalCount+=$g['finalCount'];}unset($g);
 $unmatched=array_diff_key($overrides,$groups);$unmatchedItems=[];foreach($unmatched as $id=>$count){$old=$entry['basis'][$id]??[];$unmatchedItems[]=['category'=>$old['category']??'以前の内訳','classes'=>$old['classes']??[],'finalCount'=>$count];}$excluded=in_array($teacher,staffSiteSettings(true)['payrollExcludedNames'],true);
 usort($otherLessons,function($a,$b){return strcmp($a['date'].' '.$a['start'].' '.$a['className'],$b['date'].' '.$b['start'].' '.$b['className']);});
 return ['otherLessons'=>$otherLessons,'scope'=>$scope,'revision'=>paRevision($entry),'basisRevision'=>$basis,'groups'=>array_values($groups),'overrides'=>(object)$overrides,'plannedCount'=>$plannedCount,'finalCount'=>$finalCount,'plannedPay'=>$plannedMissing?null:$planned,'finalPay'=>$missing||$unmatched?null:$final,'unmatchedCount'=>count($unmatched),'unmatched'=>$unmatchedItems,'savedAt'=>$entry['updatedAt']??null,'excludedFromTotal'=>$excluded];
}
